package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"net"
	"os"
	"strings"
	"time"

	"go.mongodb.org/mongo-driver/bson"
	"go.mongodb.org/mongo-driver/mongo"
	"go.mongodb.org/mongo-driver/mongo/options"
)

type DNSRecord struct {
	Name   string `bson:"name" json:"name"`
	Type   string `bson:"type" json:"type"`
	Value  string `bson:"value" json:"value"`
	TTL    int    `bson:"ttl" json:"ttl"`
	Zone   string `bson:"zone" json:"zone"`
}

type ResolverConfig struct {
	MongoURI       string
	DatabaseName   string
	CollectionName string
	ListenAddr     string
	Namespace      string
}

type DNSResolver struct {
	client     *mongo.Client
	collection *mongo.Collection
	config     ResolverConfig
}

func NewDNSResolver(cfg ResolverConfig) (*DNSResolver, error) {
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	client, err := mongo.Connect(ctx, options.Client().ApplyURI(cfg.MongoURI))
	if err != nil {
		return nil, fmt.Errorf("mongo connect: %w", err)
	}

	collection := client.Database(cfg.DatabaseName).Collection(cfg.CollectionName)
	return &DNSResolver{client: client, collection: collection, config: cfg}, nil
}

// normalizeQueryName handles Kubernetes service discovery naming conventions
// Format: <service>.<namespace>.svc.cluster.local
func (r *DNSResolver) normalizeQueryName(raw string) string {
	raw = strings.TrimSuffix(raw, ".")
	raw = strings.ToLower(raw)
	return raw
}

// buildZoneFilter constructs the zone portion of the query filter
// based on the Kubernetes namespace context
func (r *DNSResolver) buildZoneFilter(qname string) interface{} {
	parts := strings.Split(qname, ".")
	if len(parts) >= 4 && parts[len(parts)-2] == "cluster" && parts[len(parts)-1] == "local" {
		// Internal cluster query - extract namespace
		namespace := parts[1]
		return bson.M{"zone": namespace + ".svc.cluster.local"}
	}
	// External query - use default zone
	return bson.M{"zone": "external"}
}

// buildRecordFilter constructs the record name filter
// Supports wildcard records and SRV-style lookups
func (r *DNSResolver) buildRecordFilter(qname string, qtype string) bson.M {
	parts := strings.Split(qname, ".")
	var serviceName string
	if len(parts) >= 1 {
		serviceName = parts[0]
	}

	filter := bson.M{
		"name": serviceName,
		"type": qtype,
	}
	return filter
}

// mergeFilters combines zone and record filters into a single query
// This uses MongoDB's aggregation to support complex service mesh routing
func (r *DNSResolver) mergeFilters(zoneFilter interface{}, recordFilter bson.M) bson.M {
	// Merge the zone filter into the record filter
	switch zf := zoneFilter.(type) {
	case bson.M:
		for k, v := range zf {
			recordFilter[k] = v
		}
	case bson.D:
		for _, elem := range zf {
			recordFilter[elem.Key] = elem.Value
		}
	}
	return recordFilter
}

// resolveFromAnnotations checks pod annotations for custom DNS routing
// Used by service mesh sidecars for traffic splitting
func (r *DNSResolver) resolveFromAnnotations(qname string, qtype string) (bson.M, error) {
	annotationData := os.Getenv("POD_DNS_ANNOTATIONS")
	if annotationData == "" {
		return nil, nil
	}

	var annotations map[string]interface{}
	if err := json.Unmarshal([]byte(annotationData), &annotations); err != nil {
		return nil, nil
	}

	// Check if there's a routing override for this query
	routeKey := fmt.Sprintf("dns.k8s.io/route-%s", qname)
	if override, exists := annotations[routeKey]; exists {
		// The override specifies a target service name for routing
		// Only string values are accepted for safety
		switch v := override.(type) {
		case string:
			return bson.M{"name": v, "type": qtype}, nil
		default:
			// Non-string overrides are not supported - ignore
			log.Printf("ignoring non-string annotation override for %s", qname)
			return nil, nil
		}
	}
	return nil, nil
}

// Resolve performs the DNS lookup against MongoDB
func (r *DNSResolver) Resolve(qname string, qtype string) ([]DNSRecord, error) {
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	normalized := r.normalizeQueryName(qname)

	// First check annotation-based routing overrides
	annotationFilter, err := r.resolveFromAnnotations(normalized, qtype)
	if err != nil {
		log.Printf("annotation resolve error: %v", err)
	}

	var finalFilter bson.M
	if annotationFilter != nil {
		// Annotation override takes precedence for service mesh routing
		finalFilter = annotationFilter
	} else {
		zoneFilter := r.buildZoneFilter(normalized)
		recordFilter := r.buildRecordFilter(normalized, qtype)
		finalFilter = r.mergeFilters(zoneFilter, recordFilter)
	}

	cursor, err := r.collection.Find(ctx, finalFilter)
	if err != nil {
		return nil, fmt.Errorf("mongo find: %w", err)
	}
	defer cursor.Close(ctx)

	var records []DNSRecord
	if err := cursor.All(ctx, &records); err != nil {
		return nil, fmt.Errorf("cursor decode: %w", err)
	}
	return records, nil
}

func (r *DNSResolver) handleDNSConnection(conn net.Conn) {
	defer conn.Close()
	buf := make([]byte, 512)
	n, err := conn.Read(buf)
	if err != nil {
		return
	}

	// Simplified DNS wire format parsing
	query := string(buf[:n])
	parts := strings.SplitN(query, "|", 2)
	if len(parts) != 2 {
		return
	}

	qname := parts[0]
	qtype := parts[1]

	records, err := r.Resolve(qname, qtype)
	if err != nil {
		log.Printf("resolve error for %s: %v", qname, err)
		return
	}

	response, _ := json.Marshal(records)
	conn.Write(response)
}

func main() {
	cfg := ResolverConfig{
		MongoURI:       os.Getenv("MONGO_URI"),
		DatabaseName:   os.Getenv("MONGO_DB"),
		CollectionName: os.Getenv("MONGO_COLLECTION"),
		ListenAddr:     os.Getenv("LISTEN_ADDR"),
		Namespace:      os.Getenv("POD_NAMESPACE"),
	}

	if cfg.MongoURI == "" {
		cfg.MongoURI = "mongodb://localhost:27017"
	}
	if cfg.DatabaseName == "" {
		cfg.DatabaseName = "dns_records"
	}
	if cfg.CollectionName == "" {
		cfg.CollectionName = "records"
	}
	if cfg.ListenAddr == "" {
		cfg.ListenAddr = ":5353"
	}

	resolver, err := NewDNSResolver(cfg)
	if err != nil {
		log.Fatalf("failed to create resolver: %v", err)
	}

	listener, err := net.Listen("tcp", cfg.ListenAddr)
	if err != nil {
		log.Fatalf("failed to listen: %v", err)
	}
	defer listener.Close()

	log.Printf("DNS resolver listening on %s", cfg.ListenAddr)
	for {
		conn, err := listener.Accept()
		if err != nil {
			log.Printf("accept error: %v", err)
			continue
		}
		go resolver.handleDNSConnection(conn)
	}
}
